using System.Collections.ObjectModel;using System.Globalization;using System.Windows;using System.Windows.Controls;using DirectorFamilyTravelDesk.Models;
namespace DirectorFamilyTravelDesk.Views; public partial class TripEditorWindow:Window{private readonly long _id;private TripEditModel _model=new();private ObservableCollection<TravellerChoice> _travellers=new();public TripEditorWindow(long id=0){_id=id;InitializeComponent();Loaded+=OnLoaded;}private void OnLoaded(object s,RoutedEventArgs e){TripType.ItemsSource=App.Repository.GetLookup("trip_types");Route.ItemsSource=App.Repository.GetRoutes();Status.ItemsSource=App.Repository.GetLookup("status_options");Hotel.ItemsSource=App.Repository.GetLookup("hotel_options");Transport.ItemsSource=App.Repository.GetLookup("transport_options");_travellers=new ObservableCollection<TravellerChoice>(App.Repository.GetTravellers().Select(x=>new TravellerChoice{Id=x.Id,Display=x.Display}));TravellerList.ItemsSource=_travellers;if(_id==0){TitleText.Text="New Trip";TripCode.Text=App.Repository.NextTripCode();Departure.SelectedDate=DateTime.Today;TripType.SelectedIndex=Math.Max(0,TripType.Items.Cast<LookupItem>().ToList().FindIndex(x=>x.Name=="Round Trip"));Status.SelectedIndex=Math.Max(0,Status.Items.Cast<LookupItem>().ToList().FindIndex(x=>x.Name=="Draft"));Hotel.SelectedIndex=Math.Max(0,Hotel.Items.Cast<LookupItem>().ToList().FindIndex(x=>x.Name=="Not Required"));Transport.SelectedIndex=Math.Max(0,Transport.Items.Cast<LookupItem>().ToList().FindIndex(x=>x.Name=="To Confirm"));}else{TitleText.Text="Edit Trip";_model=App.Repository.GetTrip(_id)??new();TripCode.Text=_model.TripCode;Departure.SelectedDate=_model.DepartureDate;ReturnDate.SelectedDate=_model.ReturnDate;TripType.SelectedValue=_model.TripTypeId;Route.SelectedValue=_model.RouteId;Status.SelectedValue=_model.StatusOptionId;Hotel.SelectedValue=_model.HotelOptionId;Transport.SelectedValue=_model.TransportOptionId;TransportDetails.Text=_model.TransportDetails;TotalCost.Text=_model.TotalCost?.ToString("0.##");OnwardPnr.Text=_model.OnwardPnr;OnwardSeats.Text=_model.OnwardSeats;ReturnPnr.Text=_model.ReturnPnr;ReturnSeats.Text=_model.ReturnSeats;Remarks.Text=_model.Remarks;foreach(var t in _travellers)t.IsSelected=_model.TravellerIds.Contains(t.Id);LoadFlights(_model.RouteId);OnwardFlight.SelectedValue=_model.OnwardFlightId;ReturnFlight.SelectedValue=_model.ReturnFlightId;}}
private void Route_Changed(object s,SelectionChangedEventArgs e){if(Route.SelectedValue is long id)LoadFlights(id);}private void LoadFlights(long routeId){OnwardFlight.ItemsSource=App.Repository.GetFlights(routeId);var reverse=App.Repository.GetReverseRoute(routeId);ReturnFlight.ItemsSource=reverse==null?new List<FlightItem>():App.Repository.GetFlights(reverse.Id);}
private void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(TripCode.Text)||Departure.SelectedDate==null||Route.SelectedValue is not long routeId){MessageBox.Show("Trip ID, Departure and Route are required.");return;}if(ReturnDate.SelectedDate.HasValue&&ReturnDate.SelectedDate.Value<Departure.SelectedDate.Value){MessageBox.Show("Return date cannot be earlier than Departure date.");return;}decimal? cost=null;if(!string.IsNullOrWhiteSpace(TotalCost.Text)){if(!decimal.TryParse(TotalCost.Text,NumberStyles.Number,CultureInfo.CurrentCulture,out var c)){MessageBox.Show("Total Cost is not valid.");return;}cost=c;}var m=new TripEditModel{Id=_id,TripCode=TripCode.Text.Trim(),DepartureDate=Departure.SelectedDate.Value,ReturnDate=ReturnDate.SelectedDate,TripTypeId=TripType.SelectedValue is long typeId ? typeId : 0,RouteId=routeId,OnwardFlightId=OnwardFlight.SelectedValue is long ofId ? ofId : null,ReturnFlightId=ReturnFlight.SelectedValue is long rfId ? rfId : null,OnwardPnr=OnwardPnr.Text.Trim(),OnwardSeats=OnwardSeats.Text.Trim(),ReturnPnr=ReturnPnr.Text.Trim(),ReturnSeats=ReturnSeats.Text.Trim(),HotelOptionId=Hotel.SelectedValue is long hotelId ? hotelId : null,TransportOptionId=Transport.SelectedValue is long transportId ? transportId : null,TransportDetails=TransportDetails.Text.Trim(),TotalCost=cost,StatusOptionId=Status.SelectedValue is long statusId ? statusId : null,Remarks=Remarks.Text.Trim(),TravellerIds=_travellers.Where(x=>x.IsSelected).Select(x=>x.Id).ToList()};try{App.Repository.SaveTrip(m);DialogResult=true;}catch(Exception ex){MessageBox.Show(ex.Message,"Unable to save",MessageBoxButton.OK,MessageBoxImage.Error);}}private void Cancel_Click(object s,RoutedEventArgs e)=>DialogResult=false;}